export const zPaginatedOrderResponse = z
  .object({
    orders: z.array(zOrder).register(z.globalRegistry, {
      description: '주문 목록',
    }),
    nextCursor: z.string().nullable(),
    hasNext: z.boolean().register(z.globalRegistry, {
      description: '다음 페이지 존재 여부',
    }),
  })
  .register(z.globalRegistry, {
    description:
      '주문 목록 페이징 응답.\n- `status=OPEN`: 모든 대기 중 주문을 반환합니다. `nextCursor`는 항상 `null`, `hasNext`는 항상 `false`.\n- `status=CLOSED`: `limit` 단위로 페이징합니다. 다음 페이지가 있으면 `nextCursor`에 커서가, `hasNext`에 `true`가 내려옵니다.\n',
  });

