export const zGetOrdersQuery = z.object({
  status: z.enum(['OPEN', 'CLOSED']).register(z.globalRegistry, {
    description:
      '주문 라이프사이클 그룹 필터. 이 값은 각 주문의 세부 상태(`orders[].status`)를 **그룹화한 라벨**이며, `orders[].status` 와 값 체계가 다릅니다.\n\n- `OPEN`: 진행 중 주문 그룹 — `orders[].status` ∈ `{PENDING, PARTIAL_FILLED, PENDING_CANCEL, PENDING_REPLACE}`\n- `CLOSED`: 종료된 주문 그룹 — `orders[].status` ∈ `{FILLED, CANCELED, REJECTED, REPLACED, CANCEL_REJECTED, REPLACE_REJECTED, PARTIAL_FILLED}`\n\n예: `status=OPEN` 을 요청하면 응답의 `orders[].status` 는 개별 주문에 따라 `PENDING`, `PARTIAL_FILLED`, `PENDING_CANCEL`, `PENDING_REPLACE` 중 하나로 내려옵니다.\n',
  }),
  symbol: z
    .string()
    .regex(/^[A-Za-z0-9.\-]+$/)
    .register(z.globalRegistry, {
      description:
        "종목 심볼. 지정 시 해당 종목의 주문만 조회.\nKRX: 6자리 종목코드 (숫자 또는 영문·숫자 조합; 예: `005930`·`0101N0`), US: 영문 티커 (`AAPL`).\n영문 대/소문자, 숫자, '.', '-' 만 허용한다.\n",
    })
    .optional(),
  from: z.iso
    .date()
    .register(z.globalRegistry, {
      description:
        '조회 시작일 (inclusive, KST 기준). 주문 생성 시간(`orderedAt`) 기준. 미지정 시 전체 기간.\n',
    })
    .optional(),
  to: z.iso
    .date()
    .register(z.globalRegistry, {
      description:
        '조회 종료일 (inclusive, KST 기준). 주문 생성 시간(`orderedAt`) 기준. 미지정 시 전체 기간.\n',
    })
    .optional(),
  cursor: z
    .string()
    .register(z.globalRegistry, {
      description:
        '페이지네이션 커서. `OPEN` 에서는 무시됩니다. `CLOSED` 에서는 다음 페이지 조회에 사용됩니다.\n',
    })
    .optional(),
  limit: z
    .int()
    .gte(1)
    .lte(100)
    .register(z.globalRegistry, {
      description:
        '페이지 크기. `OPEN` 에서는 무시됩니다 (전량 반환). `CLOSED` 에서는 적용됩니다 (기본 20, 최대 100).\n',
    })
    .optional()
    .default(20),
});

